from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult
import os

def extract_tables_from_document(document_content: bytes) -> list[dict]:
    """
    Extracts table cells and row structure from a document using Azure Document Intelligence.

    Args:
        document_content: The content of the document as bytes (e.g., PDF, JPEG, PNG).

    Returns:
        A list of dictionaries, where each dictionary represents a table and contains
        its rows, with each row containing its cells.
    """
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    # Use the prebuilt-layout model for general layout extraction including tables
    poller = document_intelligence_client.begin_analyze_document(
        "prebuilt-layout", analyze_request=document_content, content_type="application/octet-stream", features=["tables"]
    )
    result: AnalyzeResult = poller.result()

    extracted_tables = []
    if result.tables:
        for table_idx, table in enumerate(result.tables):
            table_data = {
                "bounding_regions": [
                    {
                        "page_number": region.page_number,
                        "polygon": [{"x": p.x, "y": p.y} for p in region.polygon],
                    }
                    for region in table.bounding_regions
                ] if table.bounding_regions else [],
                "rows": [],
            }

            # Group cells by row index to reconstruct the table structure
            rows_dict = {}
            if table.cells:
                for cell in table.cells:
                    if cell.row_index not in rows_dict:
                        rows_dict[cell.row_index] = []
                    rows_dict[cell.row_index].append(
                        {
                            "content": cell.content,
                            "column_index": cell.column_index,
                            "row_span": cell.row_span,
                            "column_span": cell.column_span,
                            "is_header": cell.kind == "columnHeader",
                            "bounding_regions": [
                                {
                                    "page_number": region.page_number,
                                    "polygon": [{"x": p.x, "y": p.y} for p in region.polygon],
                                }
                                for region in cell.bounding_regions
                            ] if cell.bounding_regions else [],
                        }
                    )

            # Sort rows by index and cells within each row by column index
            for row_index in sorted(rows_dict.keys()):
                row_cells = sorted(rows_dict[row_index], key=lambda c: c["column_index"])
                table_data["rows"].append({"cells": row_cells})

            extracted_tables.append(table_data)

    return extracted_tables
